// gem against RubyGems 4.0.20 (testdata/oracle, generated by scripts/oracle), the osv-scalibr vectors,
// and native requirements, checked against Gem::Requirement#satisfied_by?.
import { describe, expect, it } from 'vitest'
import {
  contains,
  fromNative,
  getScheme,
  normalizeVers,
  type Scheme,
  stringifyVers,
  VersError,
} from '../../src/index.ts'
import { divergenceCount } from '../support/divergences.ts'
import { expectTotalOrder, oracleRequirements, oracleValidity, SIGN } from '../support/oracle.ts'
import { loadComparisonPairs } from '../support/vectors.ts'

const s = getScheme('gem') as Scheme

/** Asserts that each group holds equal versions and the groups are in strictly ascending order. */
function expectOrder(groups: string[][]): void {
  const ranked = groups.flatMap((g, rank) => g.map((v) => [v, rank] as const))
  for (const [a, i] of ranked) {
    for (const [b, j] of ranked) {
      expect(Math.sign(s.compare(a, b)), `${a} vs ${b}`).toBe(Math.sign(i - j))
    }
  }
}

describe('gem against RubyGems', () => {
  const valid = oracleValidity('gem')

  it('agrees on validity', () => {
    const wrong = valid
      .filter(([v, ok]) => s.isValid(v) !== ok)
      .map(([v, ok]) => `${v} (RubyGems: ${ok ? 'valid' : 'invalid'})`)
    expect(wrong).toEqual([])
  })

  it('agrees on every comparison', () => {
    const wrong = loadComparisonPairs('oracle/gem.txt')
      .filter(({ a, op, b }) => Math.sign(s.compare(a, b)) !== SIGN[op])
      .map(({ a, op, b, line }) => `line ${line}: ${a} ${op} ${b}`)
    expect(wrong).toEqual([])
  })

  it('is a total order', () => {
    const sample = valid.filter(([, ok]) => ok).map(([v]) => v)
    expectTotalOrder(
      s,
      sample.filter((_, i) => i % Math.ceil(sample.length / 400) === 0),
    )
  })
})

describe('requirements against Gem::Requirement#satisfied_by?', () => {
  const rows = oracleRequirements('gem')

  it('agrees on every requirement and version', () => {
    expect(rows.length).toBeGreaterThan(3000)
    const wrong = rows
      .filter((r) => contains(fromNative('gem', r.requirement), r.version) !== r.satisfied)
      .map(
        (r) =>
          `line ${r.line}: ${r.version} ${r.satisfied ? 'satisfies' : 'fails'} ${r.requirement}`,
      )
    expect(wrong).toEqual([])
  })

  it('every documented divergence matches an oracle row', () => {
    expect(rows.filter((r) => r.divergence).length).toBe(divergenceCount('oracle/gem-requirements'))
  })
})

describe('osv-scalibr vectors', () => {
  const files = ['osv-scalibr/rubygems-versions.txt', 'osv-scalibr/rubygems-versions-generated.txt']
  const loaded = files.map((file) => [file, loadComparisonPairs(file)] as const)

  for (const [file, pairs] of loaded) {
    it(file, () => {
      const wrong = pairs
        .filter(({ a, b }) => s.isValid(a) && s.isValid(b))
        .filter(({ a, op, b }) => Math.sign(s.compare(a, b)) !== SIGN[op])
        .map(({ a, op, b, line }) => `line ${line}: ${a} ${op} ${b}`)
      expect(wrong).toEqual([])
    })
  }

  it('skips only the versions RubyGems rejects', () => {
    // osv-scalibr parses leniently; Gem::Version.correct? rejects letters right after the first number.
    const skipped = loaded.flatMap(([, pairs]) =>
      pairs.flatMap(({ a, b }) => [a, b]).filter((v) => !s.isValid(v)),
    )
    expect(skipped).toEqual(['1beta', '1gamma'])
  })
})

describe('validity', () => {
  it.each(['1', '0', '1.0.a', '1.0a1', '1-1', '1--', '0.a', '1.0.0-beta.2', '01.A'])(
    'accepts %s',
    (v) => expect(s.isValid(v)).toBe(true),
  )

  it.each(['', ' 1', '1 ', '1.', '.1', 'a', '1a', '1-', '1..0', '1.0-', 'v1', '1_0', '1+2'])(
    'rejects %j',
    (v) => expect(s.isValid(v)).toBe(false),
  )

  it('throws on an invalid version', () => {
    expect(() => s.compare('1.0', '')).toThrow(VersError)
  })
})

describe('Gem::Version order', () => {
  it('orders pre-releases, zeros and separators', () => {
    expectOrder([
      ['0.a', '0.0.a'],
      ['0', '0.0', '00'],
      // Upper case sorts first: letters compare by byte.
      ['1.A'],
      ['1.a.a'],
      ['1.a', '1.0.a', '1.a0', '1.a.0.0'],
      ['1.a1', '1.a.1', '1.0a1', '1.0.a.1'],
      ['1.aa'],
      // `-` is read as `.pre.`.
      ['1.0.0-1', '1-1', '1.pre.1'],
      ['1', '01', '1.0', '1.0.0', '1.00'],
      ['1.0.0.1'],
      ['1.2'],
      ['1.10'],
      ['2'],
    ])
  })

  it('drops only the first run of zeros before a letter, as `sub!` does', () => {
    expectOrder([['1.0.a.b', '1.a.0.b', '1.a.b'], ['1.0.a.0.b'], ['1.0.a.1']])
  })

  it('follows the RubyGems test suite', () => {
    expectOrder([
      ['1.0.0-alpha'],
      ['1.0.0-alpha.1'],
      ['1.0.0-beta.2'],
      ['1.0.0-beta.11'],
      ['1.0.0-rc.1', '1.0.0-rc1'],
      ['1.0.0'],
    ])
    expectOrder([['0.0.beta'], ['0.beta.1', '0.0.beta.1']])
    expectOrder([['5.a'], ['5.0.0.rc2'], ['5.x']])
    expectOrder([['1.9.2.99'], ['1.9.3'], ['1.9.3.1']])
  })

  it('compares numbers of any length', () => {
    expectOrder([['999999999999999999999999999991'], ['999999999999999999999999999999']])
  })
})

describe('fromNative', () => {
  it.each([
    ['~> 2.0.8', 'vers:gem/>=2.0.8|<2.1'],
    ['~> 2.0', 'vers:gem/>=2.0|<3'],
    ['~> 2', 'vers:gem/>=2|<3'],
    ['~> 1.0.0.a', 'vers:gem/>=1.0.0.a|<1.1'],
    ['~> 1.0a1', 'vers:gem/>=1.0a1|<2'],
    ['~> 1.0-beta', 'vers:gem/>=1.0-beta|<2'],
    ['~> 01.09.3', 'vers:gem/>=01.09.3|<1.10'],
    ['~>1.99999999999999999999.0', 'vers:gem/>=1.99999999999999999999.0|<1.100000000000000000000'],
    ['>= 1.0, < 2.0', 'vers:gem/>=1.0|<2.0'],
    ['>= 1.4, <= 1.6, != 1.5', 'vers:gem/>=1.4|!=1.5|<=1.6'],
    ['~> 1.4, >= 1.4.4', 'vers:gem/>=1.4.4|<2'],
    ['!= 1.2', 'vers:gem/!=1.2'],
    ['> 1.2', 'vers:gem/>1.2'],
    ['<= 1.2', 'vers:gem/<=1.2'],
    // A bare version means `=`, as in Gem::Requirement.
    ['1.2', 'vers:gem/1.2'],
    ['= 1.2', 'vers:gem/1.2'],
    ['  >=  1.0 ,  <  2  ', 'vers:gem/>=1.0|<2'],
  ])('%s is %s', (native, vers) => {
    expect(stringifyVers(fromNative('gem', native))).toBe(vers)
  })

  it.each([
    ['', 'INVALID_SYNTAX'],
    [' ', 'INVALID_SYNTAX'],
    ['>= 1.0,', 'INVALID_SYNTAX'],
    ['! 1', 'INVALID_SYNTAX'],
    ['= junk', 'INVALID_SYNTAX'],
    ['1..2', 'INVALID_SYNTAX'],
    ['== 1.0', 'INVALID_SYNTAX'],
    ['>= 1.0 || < 0.5', 'INVALID_SYNTAX'],
    ['>= 2.0, < 1.0', 'INVALID_CONSTRAINTS'],
  ])('rejects %j with %s', (native, code) => {
    expect(() => fromNative('gem', native)).toThrow(expect.objectContaining({ code }))
  })
})

describe('containment', () => {
  it.each([
    ['vers:gem/>=2.0.8|<2.1', '2.0.9.a', true],
    ['vers:gem/>=2.0.8|<2.1', '2.1', false],
    // RubyGems rejects 2.1.a for ~> 2.0.8; see the fromNative note in src/schemes/gem.ts.
    ['vers:gem/>=2.0.8|<2.1', '2.1.a', true],
    ['vers:gem/<1.0', '1.0.a', true],
    ['vers:gem/1.0', '1.0.0', true],
    ['vers:gem/1.a', '1.0.a', true],
    ['vers:gem/>=1.0', '1-1', false],
  ] as const)('%s contains %s: %s', (range, version, expected) => {
    expect(contains(range, version)).toBe(expected)
  })

  it('sorts constraints by the RubyGems order when normalising', () => {
    expect(stringifyVers(normalizeVers('vers:gem/1.10|1.a|1.2|1.A'))).toBe(
      'vers:gem/1.A|1.a|1.2|1.10',
    )
  })
})
